export interface ConnectorConfig {
  trelloApiKey: string
  trelloApiToken: string
  idChecklist: string
  fetch?: typeof fetch
}

export interface GoogleCalendarWebhookPayload {
  event: string
  event_id: string
  account_id: string
  attendees?: Array<{ email: string }>
}

export interface HandleResult {
  checkItemId: string
  name: string
  state: string
  idChecklist: string
  idCard: string
}

export async function handle(
  payload: GoogleCalendarWebhookPayload,
  config: ConnectorConfig
): Promise<HandleResult> {
  const fetchImpl = config.fetch ?? fetch

  if (!payload.attendees || payload.attendees.length === 0) {
    throw new Error('Google Calendar webhook payload must contain at least one attendee with an email')
  }

  const firstAttendee = payload.attendees[0]
  if (!firstAttendee.email) {
    throw new Error('First attendee in Google Calendar webhook payload is missing an email field')
  }

  const email = firstAttendee.email
  const url = `https://api.trello.com/1/checklists/${encodeURIComponent(config.idChecklist)}/checkItems`

  const queryParams = new URLSearchParams({
    key: config.trelloApiKey,
    token: config.trelloApiToken,
  })

  const response = await fetchImpl(`${url}?${queryParams.toString()}`, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
    },
    body: JSON.stringify({ value: email }),
  })

  if (!response.ok) {
    throw new Error(`Trello API request failed: ${response.status} ${response.statusText} for POST ${url}`)
  }

  const data = (await response.json()) as HandleResult
  return data
}

